class LinearRegressionNumpy:
    """Simple linear regression using the Normal Equation."""

    def __init__(self, add_intercept=True):
        self.add_intercept = add_intercept
        self.coefficients_ = None
        self.intercept_ = None

    def _add_column(self, X):
        """Add intercept column of 1s if needed."""
        if self.add_intercept:
            ones = np.ones((X.shape[0], 1))
            return np.hstack([ones, X])
        return X

    def fit(self, X, y):
        """
        Fit model using Normal Equation: β = (X'X)⁻¹ X'y

        Parameters:
            X : np.ndarray of shape (n_samples, n_features)
            y : np.ndarray of shape (n_samples,)
        """
        X_augmented = self._add_column(X)
        # Normal equation with pseudo-inverse for numerical stability
        self.coefficients_ = np.linalg.pinv(X_augmented.T @ X_augmented) @ X_augmented.T @ y

        if self.add_intercept:
            self.intercept_ = self.coefficients_[0]
            self.coefs_only_ = self.coefficients_[1:]
        else:
            self.intercept_ = 0.0
            self.coefs_only_ = self.coefficients_

        return self

    def predict(self, X):
        """Make predictions: y_hat = X @ β"""
        X_augmented = self._add_column(X)
        return X_augmented @ self.coefficients_

    def score(self, X, y):
        """Return R² score."""
        y_pred = self.predict(X)
        return r2_score(y, y_pred)

    def rmse(self, y_true, y_pred=None):
        """Calculate RMSE."""
        if y_pred is None:
            y_pred = self.predict(y_true)
        return np.sqrt(mean_squared_error(y_true, y_pred))

    def summary(self):
        """Print model parameters."""
        print("=" * 55)
        print("       NUMPY LINEAR REGRESSION SUMMARY")
        print("=" * 55)
        print(f"  Intercept (β₀):  {self.intercept_:.4f}")
        for i, coef in enumerate(self.coefs_only_, 1):
            print(f"  Coefficient β{i}:  {coef:.4f}")
        print("=" * 55)
